/// <summary>
/// MPJ_5013_ExciseRegisterEntry
/// Service class to run the update Nat3040 report number
/// </summary>
class METNat3040RegisterUpdateService extends SysOperationServiceBase
{
  
}

Method.Source:
    /// <summary>
    /// MPJ_5013_ExciseRegister
    /// Checks if run in batch or not.
    /// </summary>
    public void processOperation(METNat3040RegisterUpdateContract _contract)
    {
        METExciseRegisterEntry  metExciseRegisterEntry;
        NumberSeq               num;
        Num                     number;
        NoYesId                 UpdateNat3040 = _contract.parmUpdateNat3040();
        MATNat3040ReportNumber  Nat3040Number = _contract.parmNat3040Number();

        if(UpdateNat3040 ==  NoYes::Yes)
        {
            
            ttsbegin;
            num     = NumberSeq::newGetNum(VendParameters::numRefNat30Number());
            number  = num.num();
            Nat3040Number = number;
            update_recordset metExciseRegisterEntry
                setting Nat3040ReportNumber = number
                where metExciseRegisterEntry.CustomerExempt      == NoYes::No
                &&    metExciseRegisterEntry.Nat3040ReportNumber == '';

            num.used();
            ttscommit;
        }

        this.nat30export(Nat3040Number);
        this.nat40export(Nat3040Number);
   
    }

    /// <summary>
    /// MPJ_5013_ExciseRegisterEntry
    /// based on the input parameters filter the records from METExciseRegister table and store in csv
    /// </summary>
    /// <param name = "_UpdateNat3040"> NoYesId</param>
    /// <param name = "_Nat3040Number"> Nat30/40 Report Number </param>
    private void nat30export(MATNat3040ReportNumber _Nat3040Number)
    {
        METExciseRegisterEntry  metExciseRegisterEntry;
        METTariffItemCode       metTariffItemCode;
        METInventTable          metInventTable;
        InventTable             inventtable;
        Description             TarrifItemcodeDescription;
        Qty                     CustomsValue,LQuantity,InvoiceAlcohol;

        CommaStreamIo           io          = CommaStreamIo::constructForWrite();
        Filename                fileName    = 'NAT30_.csv', fileContent;
        
        io.writeExp(['ItemNo', 'Tariff Item Code', 'Stat Code','Tariff Item Description', 'LALS Quantity',
                     'Customs Value','Origin Country Code','Preference Scheme','Preference Rule',
                     'L Quantity','Invoice alcohol']);
        
       
        
        while select sum(LitresOfAlcoholCalculated),sum(Quantity) from metExciseRegisterEntry
            group by ItemNo,TariffItemCode,DutyOriginCountryCode,DutyRate,PreferenceRule,StatCode,PreferenceScheme
            //order by ItemNo
            where metExciseRegisterEntry.OriginType             ==  METOriginType::SalesOrder
            &&    metExciseRegisterEntry.Nat3040ReportNumber    ==  _Nat3040Number
            &&    metExciseRegisterEntry.NAT3040                ==  METNAT3040::NAT30
          
       {
           //fetch tariff item code description
           select firstonly Description
               from metTariffItemCode             
                   where metTariffItemCode.TariffItem == metExciseRegisterEntry.TariffItemCode; 
            TarrifItemcodeDescription  =   metTariffItemCode.Description;

            //fetch bottel size from 
            select firstonly RecId
                from inventtable
                    where inventtable.ItemId == metExciseRegisterEntry.ItemNo;

            select firstonly InventTableRefRecid,BottleSize
                from metInventTable
                    where metInventTable.InventTableRefRecid == inventTable.RecId;

             LQuantity       =   metExciseRegisterEntry.Quantity *  metInventTable.BottleSize * -1;

             CustomsValue    =   metExciseRegisterEntry.DutyRate *  metExciseRegisterEntry.LitresOfAlcoholCalculated;


            if(LQuantity != 0)
            {
                 InvoiceAlcohol  =   (LQuantity *100)/metExciseRegisterEntry.LitresOfAlcoholCalculated;
            }

           // Write line
            io.writeExp([metExciseRegisterEntry.ItemNo,metExciseRegisterEntry.TariffItemCode,metExciseRegisterEntry.StatCode,
                         TarrifItemcodeDescription, metExciseRegisterEntry.LitresOfAlcoholCalculated,CustomsValue,metExciseRegisterEntry.DutyOriginCountryCode,
                         metExciseRegisterEntry.PreferenceScheme,metExciseRegisterEntry.PreferenceRule,LQuantity,InvoiceAlcohol]);
       
       }

            // Set stream
            System.IO.Stream stream = io.getStream();
            stream.Position = 0;

            // Set stream reader
            System.IO.StreamReader sReader = new System.IO.StreamReader(stream);

            // Set file contentn string
            fileContent = sReader.ReadToEnd();

        }

    private void nat40export(MATNat3040ReportNumber _Nat3040Number)
    {
        METExciseRegisterEntry  metExciseRegisterEntry;
        Description             Units;
        Qty                     ExciseAmount;
        CommaStreamIo           io          = CommaStreamIo::constructForWrite();
        Filename                fileName    = 'NAT40_.csv', fileContent;

        io.writeExp(['Tariff Item Code', 'LALS Quantity ','Units','Duty rate','Excise amount']);

        while select sum(LitresOfAlcoholCalculated) from metExciseRegisterEntry
            group by TariffItemCode,DutyRate
            where metExciseRegisterEntry.OriginType             == METOriginType::SalesOrder
            &&    metExciseRegisterEntry.Nat3040ReportNumber    == _Nat3040Number
            &&    metExciseRegisterEntry.NAT3040                == METNAT3040::NAT40
        {
            Units           = 'Litres of alcohol';
            ExciseAmount    = metExciseRegisterEntry.LitresOfAlcoholCalculated * metExciseRegisterEntry.DutyRate;

            io.writeExp([metExciseRegisterEntry.TariffItemCode,metExciseRegisterEntry.LitresOfAlcoholCalculated,
                        Units,metExciseRegisterEntry.DutyRate,ExciseAmount]);
        }

        // Set stream
        System.IO.Stream stream = io.getStream();
        stream.Position = 0;

        // Set stream reader
        System.IO.StreamReader sReader = new System.IO.StreamReader(stream);

        // Set file contentn string
        fileContent = sReader.ReadToEnd();
        

          
    }
